import {buildMountainBike} from './mountain-bike.mjs';
import {mergeStaticChildren} from './merge-static.mjs';
import * as T from './vendor/three.module.js';
import {generatedMap} from './generated-materials.mjs';
import {createNatureKit} from './nature.mjs';
import {createWeatherWorld} from './weather-world.mjs';
import {trackCenter,rideHeight,rampLift,RIDE_GATES,RIDE_RAMPS,RIDE_OBSTACLES,SPORTS} from './downhill.mjs';
export function createDownhillWorld(mode,{compact=false}={}){const winter=mode==='sled',scene=new T.Scene(),camera=new T.PerspectiveCamera(70,1,.1,700);scene.background=new T.Color('#bed3dd');scene.fog=new T.Fog('#bed3dd',130,420);const sun=new T.DirectionalLight('#ffe9c5',2.3);sun.position.set(-25,45,10);scene.add(sun,new T.HemisphereLight('#fff5da','#71866c',1.4));
 const mats=[],geos=[],mat=(color,options={})=>{const m=new T.MeshStandardMaterial({color,roughness:.95,...options});mats.push(m);return m;},soil=mat('#ffffff',{map:generatedMap(winter?'ride-snow':'meadow-autumn')}),pathMat=mat('#ffffff',{map:generatedMap(winter?'ride-snow':'trail-forest')}),wood=mat('#85684b'),stone=mat('#999b92'),accent=mat(winter?'#8aaac4':'#b9a168');
 const add=(g,m,x=0,y=0,z=0,parent=scene)=>{geos.push(g);const o=new T.Mesh(g,m);o.position.set(x,y,z);o.receiveShadow=true;parent.add(o);return o;};
 const terrain=new T.PlaneGeometry(100,580,65,290);terrain.rotateX(-Math.PI/2);terrain.translate(0,0,-240);const p=terrain.attributes.position,uv=terrain.attributes.uv;for(let i=0;i<p.count;i++){p.setY(i,rideHeight(p.getX(i),-p.getZ(i)));uv.setXY(i,p.getX(i)/7,-p.getZ(i)/7);}terrain.computeVertexNormals();add(terrain,soil);const v=[],u=[],ix=[];for(let i=0;i<=500;i++){const d=i-5,x=trackCenter(d),width=SPORTS[mode].width;for(const side of[-1,1]){const xx=x+side*width;v.push(xx,rideHeight(xx,d)+.035,-d);u.push(side<0?0:1,d/5);}if(i){const k=i*2;ix.push(k-2,k-1,k,k-1,k+1,k);}}const trail=new T.BufferGeometry();trail.setAttribute('position',new T.Float32BufferAttribute(v,3));trail.setAttribute('uv',new T.Float32BufferAttribute(u,2));trail.setIndex(ix);trail.computeVertexNormals();const road=add(trail,pathMat);road.material.side=T.DoubleSide;road.userData.kind='downhill-continuous-track';
 const gates=[];for(const d of RIDE_GATES){const group=new T.Group();scene.add(group);for(const side of[-1,1]){const x=trackCenter(d)+side*(SPORTS[mode].width-.4),y=rideHeight(x,d);add(new T.CylinderGeometry(.05,.05,2,8),wood,x,y+1,-d,group);add(new T.BoxGeometry(.6,.4,.04),accent,x-side*.28,y+1.6,-d,group);}gates.push(group);}
 for(const o of RIDE_OBSTACLES){const x=trackCenter(o.d)+o.offset,r=add(winter?new T.SphereGeometry(.55,12,8):new T.CylinderGeometry(.25,.27,1.5,10),winter?stone:wood,x,rideHeight(x,o.d)+.23,-o.d);if(!winter)r.rotation.z=Math.PI/2;r.userData.kind='downhill-obstacle';}
 for(const d of RIDE_RAMPS){const ramp=new T.Group();ramp.userData.kind='ride-jump-ramp';ramp.userData.lip=d;ramp.userData.length=9;ramp.userData.height=1.5;scene.add(ramp);for(let j=0;j<27;j++){const dd=d-9+(j+.5)/3,x=trackCenter(dd),y=rideHeight(x,dd)+.055,r=add(new T.BoxGeometry(3.2,.075,.325),winter?soil:wood,x,y,-dd,ramp);r.rotation.x=Math.atan2(rideHeight(trackCenter(dd+.15),dd+.15)-rideHeight(trackCenter(dd-.15),dd-.15),.3);r.rotation.y=-Math.atan2(trackCenter(dd+.1)-trackCenter(dd-.1),.2);}if(!winter)for(let j=0;j<4;j++){const dd=d-1-j*2,lift=rampLift(dd),center=trackCenter(dd),top=rideHeight(center,dd);for(const side of[-1,1]){const x=center+side*1.42;add(new T.CylinderGeometry(.065,.075,Math.max(.1,lift),8),wood,x,top-lift/2,-dd,ramp);const brace=add(new T.BoxGeometry(.08,Math.max(.1,lift)*1.2,.08),wood,x,top-lift/2,-dd+.3,ramp);brace.rotation.x=.5;}}mergeStaticChildren(ramp);}

 let seed=7189;const rnd=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};const nature=createNatureKit(scene,[],rnd,{height:(x,z)=>rideHeight(x,-z),flowerCount:winter?0:1700,grassCount:winter?0:4500,meadowWidth:90,meadowDepth:480,meadowCenterZ:-240});for(let i=0;i<(compact?130:210);i++){const d=rnd()*490,x=trackCenter(d)+(i%2?1:-1)*(7+rnd()*30);nature.tree(x,-d,.65+rnd()*1.1,i%4===0);}nature.finishTrees();if(!winter)nature.meadow((x,z)=>z<0&&z>-480&&Math.abs(x-trackCenter(-z))>5);
 const stones=new T.InstancedMesh(new T.IcosahedronGeometry(1,2),nature.rockMaterial,180),pose=new T.Object3D();for(let i=0;i<180;i++){const d=rnd()*480,x=trackCenter(d)+(i%2?1:-1)*(4.5+rnd()*18),size=.2+rnd()*.8;pose.position.set(x,rideHeight(x,d)+size*.3,-d);pose.rotation.set(rnd(),rnd()*6,rnd());pose.scale.set(size,size*.6,size*.8);pose.updateMatrix();stones.setMatrixAt(i,pose.matrix);}scene.add(stones);
 if(!winter)for(let species=0;species<4;species++){const shrubs=new T.InstancedMesh(new T.PlaneGeometry(1.5,1.2),mat('#ffffff',{map:generatedMap('alpine-bush-atlas',species),alphaTest:.45,side:T.DoubleSide}),60);for(let i=0;i<60;i++){const d=(i+species*.25)*8,x=trackCenter(d)+(i%2?1:-1)*(5.5+rnd()*4);pose.position.set(x,rideHeight(x,d)+.42,-d);pose.rotation.set(0,rnd()*6,0);pose.scale.setScalar(.6+rnd()*.7);pose.updateMatrix();shrubs.setMatrixAt(i,pose.matrix);}scene.add(shrubs);}

 const pano=new T.Mesh(new T.PlaneGeometry(450,210),new T.MeshBasicMaterial({map:generatedMap(winter?'winter-panorama':'swiss-ridge-20261018'),color:'#ffffff',fog:false}));pano.position.set(0,25,-570);pano.material.userData.nightBackdrop=true;scene.add(pano);geos.push(pano.geometry);mats.push(pano.material);
 const gear=new T.Group();camera.add(gear);scene.add(camera);const metal=mat('#3e4945',{metalness:.55,roughness:.4});if(!winter){const bar=add(new T.CylinderGeometry(.018,.018,.65,10),metal,0,-.42,-.6,gear);bar.rotation.z=Math.PI/2;for(const side of[-1,1]){const grip=add(new T.CylinderGeometry(.028,.028,.17,10),wood,side*.29,-.42,-.6,gear);grip.rotation.z=Math.PI/2;}add(new T.CylinderGeometry(.025,.025,.38,10),metal,0,-.57,-.67,gear);}else for(const x of[-.22,.22])add(new T.BoxGeometry(.09,.05,.65),wood,x,-.54,-.55,gear);
 const bike=winter?null:buildMountainBike();if(bike){bike.scale.setScalar(.85);scene.add(bike);}
 const weather=createWeatherWorld(scene,{compact,region:'ride-'+mode,height:(x,z)=>rideHeight(x,-z)});return{scene,camera,weather,sync(c,e,dt){const y=rideHeight(c.x,c.distance)+c.air;camera.position.set(c.x,y+(winter?.75:1.65),-c.distance);camera.lookAt(c.x+Math.sin(c.heading)*12,rideHeight(c.x,c.distance+12)+(winter?.7:1.1)+c.air,-c.distance-12);camera.rotation.z=-c.heading*.08;gear.rotation.z=-c.heading*.4;if(bike){bike.position.set(c.x,y+.02,-c.distance-.65);bike.rotation.set(0,Math.PI/2-c.heading,-Math.min(.35,c.vy*.035));gear.visible=false;}gates.forEach((g,i)=>g.visible=i>=c.gates.length);weather.step(dt,e,camera.position,false);},dispose(){const gs=new Set(geos),ms=new Set(mats);scene.traverse(o=>{if(o.geometry)gs.add(o.geometry);for(const m of Array.isArray(o.material)?o.material:o.material?[o.material]:[])ms.add(m);});gs.forEach(g=>g.dispose());ms.forEach(m=>m.dispose());scene.clear();}};
}
